#!/bin/sh
search_tools_menu(){ while :; do c=$(ui_menu 'Search and navigation tools' 'Install, configure, and test modern search tools.' install 'Install recommended search bundle' rg 'ripgrep configuration' fd 'fd configuration' fzf 'fzf shell integration' locate 'locate database and configuration' bat 'bat pager configuration' eza 'eza aliases' benchmark 'Search benchmark' back Back) || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; case $c in install) pkg_install ripgrep fd-find fzf bat eza 2>/dev/null || pkg_install ripgrep fd fzf bat eza;; rg) replace_block "$CURRENT_HOME/.profile" ripgrep 'export RIPGREP_CONFIG_PATH="$HOME/.config/ripgrep/config"'; mkdir -p "$CURRENT_HOME/.config/ripgrep"; write_file "$CURRENT_HOME/.config/ripgrep/config" 644 '--smart-case\n--hidden\n--glob=!.git/*\n--colors=match:style:bold';; fd) replace_block "$CURRENT_HOME/.profile" fd 'export FD_OPTIONS="--hidden --follow --exclude .git"';; fzf) ensure_tool fzf fzf && replace_block "$CURRENT_HOME/.bashrc" fzf '[ -f /usr/share/fzf/key-bindings.bash ] && . /usr/share/fzf/key-bindings.bash\n[ -f /usr/share/fzf/completion.bash ] && . /usr/share/fzf/completion.bash\nexport FZF_DEFAULT_OPTS="--height=40% --layout=reverse --border"';; locate) ensure_tool updatedb plocate && run_capture updatedb as_root updatedb;; bat) replace_block "$CURRENT_HOME/.profile" bat 'export PAGER="bat --paging=always"\nexport BAT_THEME=${BAT_THEME:-ansi}';; eza) replace_block "$CURRENT_HOME/.bashrc" eza "alias ls='eza --group-directories-first'\nalias ll='eza -lah --git --group-directories-first'\nalias tree='eza --tree'";; benchmark) d=$(ui_input Benchmark 'Directory to search' "$CURRENT_HOME") || continue; q=$(ui_input Benchmark 'Pattern' TODO) || continue; { have rg && time rg -l "$q" "$d" >/dev/null 2>&1; have grep && time grep -R -l "$q" "$d" >/dev/null 2>&1; } >"$TMP_DIR/searchbench" 2>&1; ui_text Benchmark "$(cat "$TMP_DIR/searchbench")";; back) return;; esac; done; }
